import { readFileSync } from 'node:fs';

const path = process.argv[2];
const text = readFileSync(path, 'utf8');
const lines = text.split('\n').filter((l) => l.trim());
const entries = [];
for (const l of lines) {
  try { entries.push(JSON.parse(l)); } catch { /* skip */ }
}

function truncate(s, n) {
  if (!s) return s;
  s = String(s);
  return s.length > n ? s.slice(0, n) + `…[${s.length - n} more chars]` : s;
}

for (const entry of entries) {
  const ts = entry.timestamp ?? '';
  if (entry.type === 'user' && !entry.isMeta && !entry.isSidechain) {
    const content = entry.message?.content;
    if (typeof content === 'string') {
      if (!content.trimStart().startsWith('<')) {
        console.log(`\n[${ts}] HUMAN: ${truncate(content, 1500)}`);
      }
    } else if (Array.isArray(content)) {
      for (const block of content) {
        if (block?.type === 'tool_result') {
          const c = block.content;
          const t = typeof c === 'string' ? c : Array.isArray(c) ? c.map((x) => x?.text || '').join(' ') : '';
          const isError = block.is_error ? ' ERROR' : '';
          console.log(`[${ts}] TOOL_RESULT${isError}: ${truncate(t, 300)}`);
        }
      }
    }
  } else if (entry.type === 'assistant' && !entry.isSidechain) {
    const content = entry.message?.content;
    if (Array.isArray(content)) {
      for (const block of content) {
        if (block?.type === 'text' && block.text) {
          console.log(`[${ts}] ASSISTANT: ${truncate(block.text, 800)}`);
        } else if (block?.type === 'tool_use') {
          const input = truncate(JSON.stringify(block.input || {}), 200);
          console.log(`[${ts}] TOOL_USE ${block.name}: ${input}`);
        }
      }
    }
  }
}

